// Package review — see env.go for package-level rationale.
//
// runnerconfig.go is a SPIKE (see the Slack thread of 2026-09-07 and Stefan's
// `--use-runner-config` suggestion). It runs the repo's trail runner configs
// under `.entire/runners/` as local reviewers, so a developer can see what the
// trail's runners will say before pushing instead of discovering it afterwards.
//
// It deliberately bypasses review profiles entirely: a runner config already
// names its own agent, model, prompt and timeout, so there is nothing for a
// profile to contribute. Everything here is additive — no existing review path
// changes shape.
//
// Known gaps, all deliberate for the spike:
//   - Runner configs are read from disk only. Runners defined in the UI/db
//     (the slop monitor, for one) are invisible to this.
//   - The remote runs each runner in a sandbox with a read-only repo token.
//     Locally the agent runs with the developer's own permissions and no
//     sandbox, so a committed runner template is an instruction channel into
//     the machine. That is the same class as GHSA-hqjp-v5g5-vxvf. Before this
//     ships to anyone else it needs the trust gate the OPF `command` and
//     `external_agents` settings already use.
//   - Runner timeouts are per-runner in the config but RunMulti applies one
//     shared deadline, so the longest runner's timeout governs the run.
//   - Nothing is persisted; `entire review --findings` does not see these runs.
package review

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	agenttypes "github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/entiredir"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// runnersDirName is the runner-config directory relative to the .entire root,
// which is also how it is read back through the entiredir root.
const runnersDirName = "runners"

// Runner result types this path knows how to run and render. A summary runner
// exists to fill a trail body and has no local meaning, so it is skipped.
const (
	resultTypeComments = "code_review_comments"
	resultTypeMonitor  = "trail_monitor"
	resultTypeSummary  = "trail_summary"
)

// runnerConfig is the subset of a `.entire/runners/*.json` file this path uses.
// The full schema belongs to the server; decoding only what we run keeps an
// unrelated server-side field from breaking a local run.
type runnerConfig struct {
	ID          string `json:"id"`
	DisplayName string `json:"display_name"`
	Enabled     bool   `json:"enabled"`
	Scope       string `json:"scope"`
	Runtime     struct {
		Kind      string `json:"kind"`
		Agent     string `json:"agent"`
		Model     string `json:"model"`
		TimeoutMS int    `json:"timeout_ms"`
	} `json:"runtime"`
	Prompt struct {
		Template string `json:"template"`
	} `json:"prompt"`
	Output struct {
		ResultType   string `json:"result_type"`
		TrailMonitor struct {
			Key      string `json:"key"`
			Label    string `json:"label"`
			Polarity string `json:"polarity"`
		} `json:"trail_monitor"`
	} `json:"output"`

	// file is the config's basename, used in messages when id is absent.
	file string
}

func (r runnerConfig) label() string {
	if s := strings.TrimSpace(r.DisplayName); s != "" {
		return s
	}
	return r.ID
}

// loadRunnerConfigs reads every runner config under <worktreeRoot>/.entire/runners
// and returns the ones this path can run: enabled, trail-scoped prompt runners
// that produce comments or a monitor score. Skipped configs are reported with a
// reason so a runner going missing from a local run is never silent.
func loadRunnerConfigs(worktreeRoot, filter string) (runners []runnerConfig, skipped []string, err error) {
	dir := filepath.Join(worktreeRoot, paths.EntireDir, runnersDirName)
	root, err := entiredir.OpenAtForRead(worktreeRoot)
	if err != nil {
		return nil, nil, fmt.Errorf("reading %s: %w", dir, err)
	}
	defer func() { _ = root.Close() }()

	entries, err := osroot.ReadDirNoSymlinks(root, runnersDirName)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil, fmt.Errorf("no runner configs: %s does not exist", dir)
		}
		return nil, nil, fmt.Errorf("reading %s: %w", dir, err)
	}

	want := normalizeRunnerConfigID(filter)
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		raw, readErr := entiredir.ReadFile(root, runnersDirName+"/"+e.Name())
		if readErr != nil {
			return nil, nil, fmt.Errorf("reading %s: %w", filepath.Join(dir, e.Name()), readErr)
		}
		var cfg runnerConfig
		if unmarshalErr := json.Unmarshal(raw, &cfg); unmarshalErr != nil {
			return nil, nil, fmt.Errorf("parsing %s: %w", filepath.Join(dir, e.Name()), unmarshalErr)
		}
		cfg.file = e.Name()
		if strings.TrimSpace(cfg.ID) == "" {
			cfg.ID = strings.TrimSuffix(e.Name(), ".json")
		}
		if want != "" && normalizeRunnerConfigID(cfg.ID) != want {
			continue
		}
		if reason := runnerSkipReason(cfg); reason != "" {
			skipped = append(skipped, fmt.Sprintf("%s: %s", cfg.ID, reason))
			continue
		}
		runners = append(runners, cfg)
	}

	sort.Slice(runners, func(i, j int) bool { return runners[i].ID < runners[j].ID })
	sort.Strings(skipped)
	if len(runners) == 0 {
		if want != "" {
			return nil, skipped, fmt.Errorf("no runnable runner matching %q under %s", filter, dir)
		}
		return nil, skipped, fmt.Errorf("no runnable runner configs under %s", dir)
	}
	return runners, skipped, nil
}

// runnerSkipReason names why a config is not run locally, or "" when it is.
func runnerSkipReason(cfg runnerConfig) string {
	switch {
	case !cfg.Enabled:
		return "disabled"
	case strings.TrimSpace(cfg.Prompt.Template) == "":
		return "no prompt template"
	case cfg.Runtime.Kind != "" && cfg.Runtime.Kind != "prompt_runner":
		return "runtime kind " + cfg.Runtime.Kind + " is not a prompt runner"
	case cfg.Scope != "" && cfg.Scope != "trail":
		return "scope " + cfg.Scope + " is not a trail scope"
	case cfg.Output.ResultType == resultTypeSummary:
		// A summary fills the trail body. Locally you are the one who would read
		// it, and you already know what you changed.
		return "produces a trail summary, which has no local meaning"
	case cfg.Output.ResultType != resultTypeComments && cfg.Output.ResultType != resultTypeMonitor:
		return "unsupported result type " + cfg.Output.ResultType
	}
	return ""
}

func normalizeRunnerConfigID(id string) string {
	return strings.TrimPrefix(strings.TrimSpace(id), "trail-")
}

// runnerAgentRegistryName maps a runner's agent id to the CLI's agent registry
// key. The runner configs say "claude" where the registry says "claude-code";
// the rest already agree. An unknown id returns "" and the runner is skipped
// rather than guessed at.
func runnerAgentRegistryName(runnerAgent string) string {
	switch strings.ToLower(strings.TrimSpace(runnerAgent)) {
	case "claude", "claude-code":
		return string(agent.AgentNameClaudeCode)
	case "codex":
		return string(agent.AgentNameCodex)
	case "gemini":
		return string(agent.AgentNameGemini)
	case "pi":
		return string(agent.AgentNamePi)
	default:
		return ""
	}
}

// renderRunnerPrompt fills the runner template's placeholders and prepends the
// local-scope statement.
//
// The statement is PREPENDED, not appended: the templates hand the agent
// numbered commands (`git diff origin/<base>...HEAD`) that see committed work
// only, and the whole point of running this before pushing is that the work may
// not be committed yet. Put after the template, a contradicting scope line
// reads as a footnote; put first, it reads as the governing instruction. This
// is still a contradiction the model resolves rather than a guarantee — the
// honest fix is per-runner templates that take the diff command as a variable.
func renderRunnerPrompt(cfg runnerConfig, branch, baseBranch string) string {
	template := cfg.Prompt.Template
	template = strings.ReplaceAll(template, "{{branch}}", branch)
	template = strings.ReplaceAll(template, "{{base_branch}}", baseBranch)
	// Locally there is no trail to read open findings from, so the runner sees
	// none and may repeat something already dismissed upstream.
	template = strings.ReplaceAll(template, "{{previous_findings}}", "[]")

	return localScopeStatement(branch, baseBranch) + "\n\n---\n\n" + template
}

func localScopeStatement(branch, baseBranch string) string {
	return fmt.Sprintf(
		"You are running LOCALLY on a developer's machine, before these changes are pushed, "+
			"not in the trail runner sandbox. The instructions after the divider are the trail "+
			"runner's own; follow them, with one change that overrides them where they conflict.\n\n"+
			"Scope: review the commits unique to branch %q versus %q, PLUS any uncommitted changes "+
			"in the working tree. Where the instructions below tell you to run "+
			"`git diff origin/%s...HEAD`, ALSO inspect `git diff HEAD` and `git status --porcelain`, "+
			"and treat what they show as part of the change under review. Uncommitted work is the "+
			"common case here and must not be skipped.\n\n"+
			"Everything else below applies unchanged, including the output format.",
		branch, baseBranch, baseBranch)
}

// runnerResult is one runner's parsed outcome.
type runnerResult struct {
	cfg    runnerConfig
	status reviewtypes.AgentStatus
	err    error

	// monitor fields, set when the runner produced a trail_monitor object.
	haveScore bool
	score     float64
	rationale string

	// comments, set when the runner produced code_review_comments.
	haveComments bool
	comments     []runnerComment

	// raw is the last non-empty output line, kept so an unparseable result is
	// shown rather than swallowed.
	raw string
}

type runnerComment struct {
	Severity   string  `json:"severity"`
	Confidence float64 `json:"confidence"`
	Body       string  `json:"body"`
	Location   struct {
		FilePath  string `json:"file_path"`
		StartLine int    `json:"start_line"`
		EndLine   int    `json:"end_line"`
	} `json:"location"`
}

// parseRunnerOutput applies the runner's `last_json_line` output adapter to the
// agent's narrative and decodes it according to the runner's result type.
func parseRunnerOutput(cfg runnerConfig, narrative string) runnerResult {
	res := runnerResult{cfg: cfg}
	line := lastJSONLine(narrative)
	res.raw = line
	if line == "" {
		return res
	}
	switch cfg.Output.ResultType {
	case resultTypeMonitor:
		var doc struct {
			Value     *float64 `json:"value"`
			Rationale string   `json:"rationale"`
		}
		if err := json.Unmarshal([]byte(line), &doc); err == nil && doc.Value != nil {
			res.haveScore = true
			res.score = *doc.Value
			res.rationale = strings.TrimSpace(doc.Rationale)
		}
	case resultTypeComments:
		var doc struct {
			Comments []runnerComment `json:"comments"`
		}
		// A well-formed empty array is a real result ("clean"), so decode
		// success is the signal, not a non-empty list.
		if err := json.Unmarshal([]byte(line), &doc); err == nil {
			res.haveComments = true
			res.comments = doc.Comments
		}
	}
	return res
}

// lastJSONLine returns the last line of text that parses as a JSON object,
// mirroring the runners' `last_json_line` output adapter. Scanning upward
// rather than taking the literal last line tolerates an agent that appends a
// trailing note after its JSON.
func lastJSONLine(narrative string) string {
	lines := strings.Split(narrative, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		line = strings.TrimPrefix(line, "```json")
		line = strings.TrimSuffix(line, "```")
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "{") || !strings.HasSuffix(line, "}") {
			continue
		}
		if !json.Valid([]byte(line)) {
			continue
		}
		return line
	}
	return ""
}

// printRunnerResults renders one block per runner: monitors as a score with
// their polarity and rationale, the review runner as its comment list. There is
// no consolidating judge — each runner's own verdict is what the trail would
// show, and putting a judge over five different output shapes would only
// reinterpret numbers the remote reports verbatim.
func printRunnerResults(w io.Writer, results []runnerResult) {
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Runner results")
	fmt.Fprintln(w)

	for _, res := range results {
		fmt.Fprintf(w, "  %s (%s)\n", res.cfg.label(), res.cfg.ID)
		switch {
		case res.err != nil:
			fmt.Fprintf(w, "    failed: %v\n", res.err)
		case res.haveScore:
			fmt.Fprintf(w, "    %s %.0f/100 (%s)\n",
				monitorLabel(res.cfg), res.score, polarityPhrase(res.cfg.Output.TrailMonitor.Polarity))
			if res.rationale != "" {
				fmt.Fprintf(w, "    %s\n", res.rationale)
			}
		case res.haveComments && len(res.comments) == 0:
			fmt.Fprintln(w, "    no comments")
		case res.haveComments:
			fmt.Fprintf(w, "    %s\n", pluralComments(len(res.comments)))
			for _, c := range res.comments {
				fmt.Fprintf(w, "      %s\n", formatRunnerComment(c))
			}
		case res.raw != "":
			fmt.Fprintf(w, "    unrecognized result: %s\n", truncateForDisplay(res.raw, 200))
		default:
			fmt.Fprintln(w, "    no result (the runner produced no JSON output line)")
		}
		fmt.Fprintln(w)
	}

	fmt.Fprintln(w, "These ran locally against your working tree, not in the trail sandbox.")
	fmt.Fprintln(w, "The trail's own runners can still disagree; this is a preview, not a verdict.")
}

func monitorLabel(cfg runnerConfig) string {
	if s := strings.TrimSpace(cfg.Output.TrailMonitor.Label); s != "" {
		return s
	}
	if s := strings.TrimSpace(cfg.Output.TrailMonitor.Key); s != "" {
		return s
	}
	return "score"
}

func polarityPhrase(polarity string) string {
	switch strings.TrimSpace(polarity) {
	case "higher_is_better":
		return "higher is better"
	case "lower_is_better":
		return "lower is better"
	default:
		return "no polarity declared"
	}
}

func pluralComments(n int) string {
	if n == 1 {
		return "1 comment"
	}
	return fmt.Sprintf("%d comments", n)
}

func formatRunnerComment(c runnerComment) string {
	severity := strings.TrimSpace(c.Severity)
	if severity == "" {
		severity = "unrated"
	}
	loc := strings.TrimSpace(c.Location.FilePath)
	if loc != "" && c.Location.StartLine > 0 {
		loc = fmt.Sprintf("%s:%d", loc, c.Location.StartLine)
	}
	body := strings.Join(strings.Fields(c.Body), " ")
	parts := []string{"[" + severity + "]"}
	if loc != "" {
		parts = append(parts, loc)
	}
	if c.Confidence > 0 {
		parts = append(parts, fmt.Sprintf("(confidence %.2f)", c.Confidence))
	}
	if body != "" {
		parts = append(parts, body)
	}
	return strings.Join(parts, " ")
}

func truncateForDisplay(s string, max int) string {
	if len(s) <= max {
		return s
	}
	return s[:max] + "…"
}

// runRunnerConfigReview is the `--use-runner-config` path. It reads the repo's
// runner configs, launches one reviewer per runner concurrently, and prints
// each runner's own result.
//
// It always exits 0 on a completed run, findings or not. This is meant to sit
// in front of a push, and a preview that fails the shell on a low-confidence
// score would be a preview nobody runs.
func runRunnerConfigReview(
	ctx context.Context,
	cmd *cobra.Command,
	runnerFilter, baseOverride string,
	timeout time.Duration,
	deps Deps,
	out io.Writer,
) error {
	silentErr := deps.NewSilentError
	errOut := cmd.ErrOrStderr()

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(errOut, "Not a git repository. Run `entire enable` first.")
		return silentErr(errors.New("not a git repository"))
	}

	runners, skipped, err := loadRunnerConfigs(worktreeRoot, runnerFilter)
	for _, s := range skipped {
		fmt.Fprintf(errOut, "skipping runner %s\n", s)
	}
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(errOut, err.Error())
		return silentErr(err)
	}

	branch, baseBranch, scopeErr := runnerScope(ctx, worktreeRoot, baseOverride, out)
	if scopeErr != nil {
		cmd.SilenceUsage = true
		return scopeErr
	}

	installed := map[string]struct{}{}
	for _, name := range deps.GetAgentsWithHooksInstalled(ctx) {
		installed[string(name)] = struct{}{}
	}

	reviewers, configs, maxTimeout := buildRunnerReviewers(runnerReviewerInputs{
		runners:    runners,
		branch:     branch,
		baseBranch: baseBranch,
		installed:  installed,
		reviewerFor: func(name string) reviewtypes.AgentReviewer {
			return deps.ReviewerFor(name)
		},
		errOut: errOut,
	})
	if len(reviewers) == 0 {
		cmd.SilenceUsage = true
		err := errors.New("no runner is runnable here: every runner's agent is missing hooks or a review runner adapter")
		fmt.Fprintln(errOut, err.Error())
		return silentErr(err)
	}

	fmt.Fprintf(out, "Running %d runner config(s) from .entire/runners locally.\n", len(reviewers))

	runCtx, cancelRun := context.WithCancel(ctx)
	defer cancelRun()

	names := make([]string, len(reviewers))
	for i, r := range reviewers {
		names[i] = r.Name()
	}
	// No synthesis provider: each runner's own output is the deliverable.
	sinks := composeMultiAgentSinks(multiAgentSinkInputs{
		out:        out,
		isTTY:      reviewCommandIsInteractive(cmd),
		agentNames: names,
		cancelRun:  cancelRun,
		runContext: runCtx,
	})
	if tuiSink, ok := findTUISink(sinks); ok {
		tuiSink.Start()
		defer tuiSink.Wait()
	}

	// RunMulti applies one deadline to every reviewer, so the longest runner's
	// own timeout governs the run. An explicit --timeout wins.
	effectiveTimeout := timeout
	if effectiveTimeout == 0 {
		effectiveTimeout = maxTimeout
	}
	summary, waitErr := RunMulti(runCtx, reviewers, reviewtypes.RunConfig{ReviewerTimeout: effectiveTimeout}, sinks)
	if shouldAbortMultiReview(summary, waitErr) && runCtx.Err() == nil && ctx.Err() == nil {
		cmd.SilenceUsage = true
		return multiReviewFailureError(waitErr)
	}

	printRunnerResults(out, collectRunnerResults(summary, configs))
	return nil
}

// runnerReviewerInputs collects what buildRunnerReviewers needs, keeping the
// signature readable and the helper testable without a cobra command.
type runnerReviewerInputs struct {
	runners     []runnerConfig
	branch      string
	baseBranch  string
	installed   map[string]struct{}
	reviewerFor func(string) reviewtypes.AgentReviewer
	errOut      io.Writer
}

// buildRunnerReviewers turns runner configs into launchable reviewers, one per
// runner. Runners naming an agent this machine cannot launch are dropped with a
// note rather than failing the whole run: four working previews beat none.
//
// configs is parallel to the returned reviewers, so a result can be matched
// back to the runner that produced it by index. maxTimeout is the largest
// per-runner timeout, which the caller uses as the shared deadline.
func buildRunnerReviewers(in runnerReviewerInputs) (reviewers []reviewtypes.AgentReviewer, configs []runnerConfig, maxTimeout time.Duration) {
	for _, cfg := range in.runners {
		agentName := runnerAgentRegistryName(cfg.Runtime.Agent)
		if agentName == "" {
			fmt.Fprintf(in.errOut, "skipping runner %s: unknown agent %q\n", cfg.ID, cfg.Runtime.Agent)
			continue
		}
		if _, ok := in.installed[agentName]; !ok {
			fmt.Fprintf(in.errOut, "skipping runner %s: hooks are not installed for %s (run `entire configure --agent %s`)\n", cfg.ID, agentName, agentName)
			continue
		}
		inner := in.reviewerFor(agentName)
		if inner == nil {
			fmt.Fprintf(in.errOut, "skipping runner %s: %s has no review runner adapter\n", cfg.ID, agentName)
			continue
		}
		if _, agErr := agent.Get(agenttypes.AgentName(agentName)); agErr != nil {
			fmt.Fprintf(in.errOut, "skipping runner %s: %v\n", cfg.ID, agErr)
			continue
		}
		if d := time.Duration(cfg.Runtime.TimeoutMS) * time.Millisecond; d > maxTimeout {
			maxTimeout = d
		}
		reviewers = append(reviewers, &perAgentConfiguredReviewer{
			name:  cfg.ID,
			inner: inner,
			cfg: reviewtypes.RunConfig{
				// PromptOverride sends the runner's own prompt verbatim, without
				// review's task/skills/scope composition. Fidelity to what the
				// trail runner sends is the entire point.
				PromptOverride: renderRunnerPrompt(cfg, in.branch, in.baseBranch),
				ProfileName:    cfg.ID,
				Model:          strings.TrimSpace(cfg.Runtime.Model),
			},
		})
		configs = append(configs, cfg)
	}
	return reviewers, configs, maxTimeout
}

// collectRunnerResults pairs each agent run with the runner config that
// produced it and parses its output. RunMulti preserves reviewer order in
// summary.AgentRuns, which is what makes the index pairing sound; the ID check
// guards that assumption rather than trusting it.
func collectRunnerResults(summary reviewtypes.RunSummary, configs []runnerConfig) []runnerResult {
	byID := make(map[string]runnerConfig, len(configs))
	for _, cfg := range configs {
		byID[cfg.ID] = cfg
	}
	results := make([]runnerResult, 0, len(summary.AgentRuns))
	for i, run := range summary.AgentRuns {
		cfg, ok := byID[run.Name]
		if !ok {
			if i < len(configs) {
				cfg = configs[i]
			} else {
				cfg = runnerConfig{ID: run.Name}
			}
		}
		res := parseRunnerOutput(cfg, joinAssistantText(run.Buffer))
		res.status = run.Status
		res.err = run.Err
		results = append(results, res)
	}
	return results
}

// runnerScope resolves the branch and base branch the runner templates
// interpolate. The templates spell the base as `origin/{{base_branch}}`, so the
// value must be the bare branch name — passing "origin/main" through would
// produce "origin/origin/main".
func runnerScope(ctx context.Context, worktreeRoot, baseOverride string, out io.Writer) (branch, baseBranch string, err error) {
	repo, openErr := gitrepo.OpenPath(worktreeRoot)
	if openErr != nil {
		return "", "", fmt.Errorf("open repository at %q: %w", worktreeRoot, openErr)
	}
	defer repo.Close()

	stats, statsErr := ComputeScopeStats(ctx, repo, baseOverride)
	if statsErr != nil {
		return "", "", fmt.Errorf("resolve review scope: %w", statsErr)
	}
	fmt.Fprintln(out, formatScopeBanner(stats))

	branch = strings.TrimSpace(stats.CurrentBranch)
	if branch == "" {
		branch = "HEAD"
	}
	baseBranch = strings.TrimPrefix(strings.TrimSpace(stats.BaseRef), "origin/")
	if baseBranch == "" {
		baseBranch = "main"
	}
	return branch, baseBranch, nil
}

// runnerConfigFlagConflict names the first flag given alongside
// --use-runner-config that the runner path cannot honor, or "" when there is
// none. The flags it rejects all select something a runner config already
// carries (its agent, its model, its prompt) or select a different command mode
// entirely; honoring them silently would make the local run diverge from the
// remote runner it exists to predict.
func runnerConfigFlagConflict(
	configure, edit, findings, listProfiles, listAgents, listModels bool,
	agentOverride, modelOverride, profileOverride, perRunPrompt string,
	args []string,
) string {
	for _, c := range []struct {
		set  bool
		name string
	}{
		{configure, "--configure"},
		{edit, "--edit"},
		{findings, "--findings"},
		{listProfiles, "--list"},
		{listAgents, "--agents"},
		{listModels, "--models"},
		{strings.TrimSpace(agentOverride) != "", "--agent"},
		{strings.TrimSpace(modelOverride) != "", "--model"},
		{strings.TrimSpace(profileOverride) != "", "--profile"},
		{strings.TrimSpace(perRunPrompt) != "", "--prompt"},
		{len(args) > 0, "a profile argument"},
	} {
		if c.set {
			return c.name
		}
	}
	return ""
}

// Package review — see env.go for package-level rationale.
//
// cmd.go provides NewCommand(), the cobra entry point for `entire review`.
// It routes through the new AgentReviewer / Sink / Run architecture for
// agents with review-runner adapters (claude-code, codex, gemini, pi) and falls
// back to RunMarkerFallback for agents that are not yet wired into that review
// runner contract.
package review

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"slices"
	"sort"
	"strings"
	"sync"
	"time"

	"charm.land/huh/v2"
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/gitexec"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// Deps collects the runtime-injectable hooks NewCommand needs from the
// parent cli package. Tests stub fields to drive branches that would
// otherwise require a real TTY or enabled repo. Production wiring is
// provided by buildReviewDeps in cmd/entire/cli/review_bridge.go and
// passed to NewCommand from root.go.
type Deps struct {
	// GetAgentsWithHooksInstalled returns the registry names of all agents
	// whose lifecycle hooks are installed in the current repo.
	GetAgentsWithHooksInstalled func(ctx context.Context) []types.AgentName

	// NewSilentError wraps an error so the cobra root does not double-print it.
	NewSilentError func(err error) error

	// HeadHasReviewCheckpoint checks whether HEAD's checkpoint metadata
	// includes a review session. Returns (true, infoString) if HasReview is set.
	// Injected to avoid an import cycle: review → checkpoint → codex → review.
	HeadHasReviewCheckpoint func(ctx context.Context) (bool, string)

	// ReviewCheckpointContext returns best-effort checkpoint context for the
	// branch review scope. Injected from the cli package because checkpoint
	// readers cannot be imported here without cycling through agent reviewers.
	ReviewCheckpointContext func(ctx context.Context, worktreeRoot string, scopeBaseRef string) string

	// ReviewerFor maps an agent registry name to its AgentReviewer
	// implementation. Returns nil for agents that do not yet have a review-runner
	// adapter. Injected to break the import cycle:
	// per-agent reviewer packages import review (for ComposeReviewPrompt /
	// AppendReviewEnv), so review/cmd.go cannot import them back.
	ReviewerFor func(agentName string) reviewtypes.AgentReviewer

	// PostReviewToTrail posts the final review verdict to the current branch's
	// trail as a finding (the "trail" output destination). Injected from the cli
	// package because the data API + auth live there. It prints its own success
	// line to out. nil when trail delivery is unavailable (e.g. tests), in which
	// case the run falls back to local output with a notice.
	PostReviewToTrail func(ctx context.Context, out io.Writer, profileName, verdict string) error

	// PrepareTarget resolves a branch, trail ID, or trail URL and checks its
	// branch out in a worktree. It returns the worktree in which review should
	// be re-run. Injected because trail API access lives in the parent package.
	PrepareTarget func(ctx context.Context, out, errOut io.Writer, selector string) (TargetWorktree, error)

	// RemoveTarget removes a worktree created specifically for this review.
	// Reused worktrees are never passed to it.
	RemoveTarget func(ctx context.Context, worktreeRoot string) error

	// RunInWorktree re-runs the current CLI invocation in worktreeRoot after the
	// target flags have been removed. nil uses the production subprocess runner.
	RunInWorktree func(ctx context.Context, worktreeRoot string, args, env []string, stdin io.Reader, stdout, stderr io.Writer) error
}

// NewCommand returns the `entire review` cobra command wired with the
// provided deps. Callers in the cli package pass a fully-populated Deps;
// tests pass a Deps with stub fields.
func NewCommand(deps Deps) *cobra.Command {
	var configure bool
	var edit bool
	var agentOverride string
	var modelOverride string
	var baseOverride string
	var profileOverride string
	var perRunPrompt string
	var findings bool
	var listModels bool
	var listAgents bool
	var listProfiles bool
	var setAgents []string
	var setJudge string
	var setOutput string
	var setLocal bool
	var reviewTimeout time.Duration
	var setTask string
	var setModels []string
	var setSlots []string
	var target string
	var cleanupWorktree bool
	var useRunnerConfig bool
	var runnerFilter string

	cmd := &cobra.Command{
		Use: "review",
		// Hidden from `entire help` while the feature is still maturing —
		// users who know about it can still run `entire review` / `entire
		// review --help` and the command works normally.
		Hidden: true,
		Short:  "Run a multi-agent review against a branch",
		Long: `Run a multi-agent review against the current branch or a --target branch:
several reviewer agents review the change in parallel, then a single judge consolidates their
reports into the final verdict in a closing round. Reviews are saved as named
profiles in Entire settings and clone-local preferences. On first run, guided
setup writes a profile and asks before starting agents.

Flags:
  --configure    set up a review profile (shows available agents + profiles).
                 With --set-* flags it writes the profile non-interactively;
                 otherwise it opens the wizard (interactive) without starting agents.
  --set-agents   with --configure: comma-separated reviewer agents for the profile
  --set-judge    with --configure: the consolidating judge as agent[=model]
  --set-output   with --configure: where the verdict goes: local (default) or trail
  --local        with --configure: save to .entire/settings.local.json (just you)
                 instead of .entire/settings.json (shared). Interactive setup asks.
  --set-task     with --configure: the profile's canonical task text
  --set-model    with --configure: per-reviewer model as agent=model (repeatable)
  --set-slot     with --configure: a reviewer slot as agent[=model] (repeatable;
                 the same agent/model may repeat to run it multiple times)
  --edit         re-open the advanced profile skill picker
  --findings     browse local findings; pass a handle to print one saved run
  --agent NAME   run only one reviewer from the selected profile
  --list         list configured review profiles (their reviewers and judge)
  --agents       list the reviewer agents you can pass to --agent for the profile
  --model NAME   override the model for the --agent reviewer (requires --agent)
  --models       list the models each agent advertises (optionally --agent NAME)
  --profile NAME select a profile (also accepted as positional arg)
  --prompt TEXT  add one-off per-run instructions for this invocation
  --timeout DUR  optional hard cap on each reviewer before it's cancelled and
                 marked failed. No default — reviewers run until they finish,
                 like a directly-invoked skill. A positive value also bounds
                 the consolidating judge, which otherwise keeps its own 20m
                 default (the judge is never unbounded; its timeout or error
                 fails the review with no verdict). A timed-out reviewer's
                 siblings and the judge still proceed.
  --base REF     scope against REF instead of mainline. Useful for stacked
                 PRs where the base is the parent feature branch, not main.
                 Default: first existing of origin/HEAD, origin/main,
                 origin/master, main, master.
  --target REF   check out a branch identified by branch name, trail ID, or
                 Entire trail URL in a worktree and run the review there.
  --cleanup-worktree
                 remove a newly-created target worktree after a successful
                 review. Interactive runs ask when this flag is omitted.

To tag an already-finished session as a review, use
'entire session attach --review <id>'.`,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most one argument, received %d", len(args))
			}
			if len(args) == 1 && profileOverride != "" && !findings {
				return errors.New("pass profile either positionally or with --profile, not both")
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			if target != "" {
				modeSelected := configure || edit || findings || listProfiles || listAgents || listModels
				return runTargetReview(ctx, cmd, target, reviewTargetChildArgs(cmd, args), cleanupWorktree, modeSelected, deps)
			}
			if cleanupWorktree {
				return errors.New("--cleanup-worktree requires --target")
			}

			// Discover external agents so review configs that target them
			// resolve correctly — without this, GetAgentsWithHooksInstalled
			// and agent.Get can't see them.
			external.DiscoverAndRegister(ctx)

			// SPIKE: --use-runner-config bypasses review profiles entirely and
			// runs the repo's .entire/runners configs locally. See
			// runnerconfig.go. It is checked before every other mode because a
			// runner config already carries its own agent, model, prompt and
			// timeout, so nothing a profile flag selects applies to it.
			if useRunnerConfig {
				if conflict := runnerConfigFlagConflict(configure, edit, findings, listProfiles, listAgents, listModels,
					agentOverride, modelOverride, profileOverride, perRunPrompt, args); conflict != "" {
					cmd.SilenceUsage = true
					return fmt.Errorf("--use-runner-config cannot be combined with %s; a runner config carries its own agent, model and prompt", conflict)
				}
				return runRunnerConfigReview(ctx, cmd, runnerFilter, baseOverride, reviewTimeout, deps, cmd.OutOrStdout())
			}
			if runnerFilter != "" {
				cmd.SilenceUsage = true
				return errors.New("--runner requires --use-runner-config")
			}

			if listModels {
				return runReviewListModels(ctx, cmd, agentOverride, deps)
			}
			if listAgents {
				listProfile := profileOverride
				if len(args) == 1 {
					listProfile = args[0]
				}
				return runReviewListAgents(ctx, cmd, listProfile, deps)
			}
			if listProfiles {
				return runReviewListProfiles(ctx, cmd, deps)
			}

			modes := 0
			for _, enabled := range []bool{configure, edit, findings} {
				if enabled {
					modes++
				}
			}
			if modes > 1 {
				return errors.New("--configure, --edit, and --findings are mutually exclusive")
			}
			if modelOverride != "" && agentOverride == "" {
				return errors.New("--model requires --agent (the model applies to a single reviewer)")
			}
			positionalArg := ""
			if len(args) == 1 {
				positionalArg = args[0]
			}
			profileName := profileOverride
			if positionalArg != "" && !findings {
				profileName = positionalArg
			}
			if configure {
				return runReviewConfigure(ctx, cmd, profileName, reviewConfigureOptions{
					Agents: setAgents,
					Judge:  setJudge,
					Output: setOutput,
					Local:  setLocal,
					Task:   setTask,
					Models: setModels,
					Slots:  setSlots,
				}, deps)
			}
			if edit {
				if !reviewCommandIsInteractive(cmd) {
					err := errors.New("--edit requires an interactive terminal")
					cmd.SilenceUsage = true
					fmt.Fprintln(cmd.ErrOrStderr(), "--edit requires an interactive terminal.")
					fmt.Fprintln(cmd.ErrOrStderr(), "Inspect current profiles with:")
					fmt.Fprintln(cmd.ErrOrStderr(), "  entire review --list")
					fmt.Fprintln(cmd.ErrOrStderr(), "For non-interactive changes, use:")
					fmt.Fprintln(cmd.ErrOrStderr(), "  entire review --configure --set-agents <agent>[,<agent>] [--set-judge <agent>]")
					return wrapReviewSilentError(deps.NewSilentError, err)
				}
				return RunReviewProfileConfigPicker(ctx, cmd.OutOrStdout(), deps.GetAgentsWithHooksInstalled, profileName)
			}
			if findings {
				return runReviewFindings(ctx, cmd, positionalArg, deps.NewSilentError)
			}
			// The flag flows through unmapped: RunConfig.ReviewerTimeout is
			// two-state (positive = hard cap, anything else = no cap), so the
			// default 0, an explicit --timeout 0, and a negative all mean
			// "reviewers run until done". The judge derives its own bound via
			// judgeTimeoutArg and is never uncapped.
			return runReview(ctx, cmd, agentOverride, modelOverride, baseOverride, profileName, perRunPrompt, reviewTimeout, deps)
		},
	}
	cmd.Flags().BoolVar(&useRunnerConfig, "use-runner-config", false, "SPIKE: review with the repo's .entire/runners trail runner configs instead of a review profile")
	cmd.Flags().StringVar(&runnerFilter, "runner", "", "with --use-runner-config: run only this runner id (the leading \"trail-\" is optional)")
	cmd.Flags().BoolVar(&configure, "configure", false, "set up a review profile; shows available agents and accepts --set-* flags for non-interactive config")
	cmd.Flags().StringSliceVar(&setAgents, "set-agents", nil, "with --configure: reviewer agents for the profile (comma-separated)")
	cmd.Flags().StringVar(&setJudge, "set-judge", "", "with --configure: the consolidating judge as agent[=model]")
	cmd.Flags().StringVar(&setOutput, "set-output", "", "with --configure: where the verdict is delivered (local or trail)")
	cmd.Flags().BoolVar(&setLocal, "local", false, "with --configure: save the profile to .entire/settings.local.json (per-developer) instead of .entire/settings.json")
	cmd.Flags().StringVar(&setTask, "set-task", "", "with --configure: the profile's canonical task text")
	cmd.Flags().StringArrayVar(&setModels, "set-model", nil, "with --configure: per-reviewer model as agent=model (repeatable)")
	cmd.Flags().StringArrayVar(&setSlots, "set-slot", nil, "with --configure: a reviewer slot as agent[=model] (repeatable; same agent/model may repeat)")
	cmd.Flags().BoolVar(&edit, "edit", false, "re-open the advanced review profile skill picker")
	cmd.Flags().BoolVar(&findings, "findings", false, "browse local review findings; pass a handle to print one saved run")
	cmd.Flags().BoolVar(&listAgents, "agents", false, "list the reviewer agents you can pass to --agent for the selected profile")
	cmd.Flags().BoolVar(&listModels, "models", false, "list the models each review agent advertises (optionally filtered by --agent)")
	cmd.Flags().BoolVar(&listProfiles, "list", false, "list configured review profiles (reviewers and judge)")
	cmd.Flags().StringVar(&agentOverride, "agent", "", "run one configured reviewer from the selected profile")
	cmd.Flags().StringVar(&modelOverride, "model", "", "override the model for the --agent reviewer (requires --agent)")
	cmd.Flags().StringVar(&profileOverride, "profile", "", "review profile to run (default: review_default_profile or general)")
	cmd.Flags().StringVar(&perRunPrompt, "prompt", "", "one-off instructions appended to this review run")
	cmd.Flags().StringVar(&baseOverride, "base", "", "git ref to scope the review against (default: origin/HEAD → origin/main → origin/master → main → master)")
	cmd.Flags().StringVar(&target, "target", "", "branch, trail ID, or Entire trail URL to check out in a worktree and review")
	cmd.Flags().BoolVar(&cleanupWorktree, "cleanup-worktree", false, "remove a newly-created target worktree after a successful review (interactive runs ask when omitted)")
	cmd.Flags().DurationVar(&reviewTimeout, "timeout", 0, "optional hard cap per reviewer (default: none — reviewers run until they finish, like a skill invoked directly in a session). When set, it also bounds the consolidating judge; unset, the judge keeps its own 20m default")
	// The listing modes and the action modes each select a distinct command
	// behavior; combining them silently runs one and drops the rest, so reject
	// the combination up front with a clear cobra error.
	cmd.MarkFlagsMutuallyExclusive("configure", "edit", "findings", "list", "agents", "models")
	return cmd
}

// reviewConfigureOptions carries the non-interactive `--configure` inputs.
type reviewConfigureOptions struct {
	Agents []string // reviewer agent names (--set-agents)
	Judge  string   // consolidating judge as "agent[=model]" (--set-judge)
	Output string   // output destination: local|trail (--set-output)
	Local  bool     // save to local settings file instead of project (--local)
	Task   string   // profile task text (--set-task)
	Models []string // per-reviewer "agent=model" entries (--set-model)
	Slots  []string // reviewer slots as "agent[=model]" entries (--set-slot)
}

// reviewCommandIsInteractive requires the exact stdin consumed by huh and
// Bubble Tea, plus stdout, to be terminals. CanPromptInteractively adds the
// independent policy gate for tests, CI, and agent subprocess sentinels; a
// controlling /dev/tty alone is insufficient because stdin may still be piped.
func reviewCommandIsInteractive(cmd *cobra.Command) bool {
	hardDisabled := reviewInteractivityHardDisabled(
		os.Getenv(interactive.EnvTestTTY),
		os.Getenv("CI"),
		interactive.UnderTest(),
	)
	return reviewTTYIsInteractive(
		interactive.IsTerminalReader(cmd.InOrStdin()),
		interactive.IsTerminalWriter(cmd.OutOrStdout()),
		interactive.CanPromptInteractively(),
		hardDisabled,
	)

